#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FileSizeStrings {
    language: Language,
}

impl FileSizeStrings {
    pub fn bytes(self, bytes: i64) -> String {
        let bytes = bytes as f64;
        match self.language {
            Language::English => if super::is_plural_one(Language::English, bytes) { format!("{} byte", super::format_number_like_javascript(bytes)) } else { format!("{} bytes", super::format_number_like_javascript(bytes)) },
            Language::French => if super::is_plural_one(Language::French, bytes) { format!("{}\u{a0}octet", super::format_count(Language::French, bytes)) } else { format!("{}\u{a0}octets", super::format_count(Language::French, bytes)) },
        }
    }

    pub fn in_unit(self, value: &str, unit: KbOrMbOrGb) -> String {
        match self.language {
            Language::English => format!("{value} {unit}"),
            Language::French => format!("{value}\u{a0}{}", match unit { KbOrMbOrGb::Kb => "Ko", KbOrMbOrGb::Mb => "Mo", KbOrMbOrGb::Gb => "Go" }),
        }
    }
}

