/// The web catalogue's union `"KB" | "MB" | "GB"`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KbOrMbOrGb {
    Kb,
    Mb,
    Gb,
}

impl std::fmt::Display for KbOrMbOrGb {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(match self {
            Self::Kb => "KB",
            Self::Mb => "MB",
            Self::Gb => "GB",
        })
    }
}

/// The web catalogue's union `"minutes" | "hours" | "days"`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MinutesOrHoursOrDays {
    Minutes,
    Hours,
    Days,
}

impl std::fmt::Display for MinutesOrHoursOrDays {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(match self {
            Self::Minutes => "minutes",
            Self::Hours => "hours",
            Self::Days => "days",
        })
    }
}

/// The web catalogue's union `"permissions" | "allow" | "deny"`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PermissionsOrAllowOrDeny {
    Permissions,
    Allow,
    Deny,
}

impl std::fmt::Display for PermissionsOrAllowOrDeny {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(match self {
            Self::Permissions => "permissions",
            Self::Allow => "allow",
            Self::Deny => "deny",
        })
    }
}

fn member_count_in_english(members: f64) -> String {
    format!("{} {}", super::format_count(Language::English, members), if super::is_plural_one(Language::English, members) { "member" } else { "members" })
}

fn participant_names_in_english(names: &[&str]) -> String {
    let first = names.first().copied();
    let second = names.get(1).copied();
    let third = names.get(2).copied();
    let Some(first) = first else {
        return "Just you".to_owned();
    };
    let Some(second) = second else {
        return first.to_owned();
    };
    if (names.len() as f64) == 2.0 {
        return format!("{first} and {second}");
    }
    if (names.len() as f64) == 3.0 && let Some(third) = third {
        return format!("{first}, {second} and {third}");
    }
    let others = names.len() as f64 - 2.0;
    format!("{first}, {second} and {} {}", super::format_count(Language::English, others), if super::is_plural_one(Language::English, others) { "other" } else { "others" })
}

fn places_in_english(places: &[&str]) -> String {
    if (places.len() as f64) <= 1.0 { places.first().copied().unwrap_or("").to_owned() } else { format!("{} and {}", places[..places.len().saturating_sub(1)].join(", "), places.last().copied().unwrap_or("")) }
}

fn member_count_in_french(members: f64) -> String {
    format!("{} {}", super::format_count(Language::French, members), if super::is_plural_one(Language::French, members) { "membre" } else { "membres" })
}

